const body = $json.body || $json;
let sender = body?.whatsappInboundMessage?.from || body?.from || '';
let message = body?.whatsappInboundMessage?.text?.body || body?.text?.body;

if (!message && body?.whatsappInboundMessage?.interactive) {
  const interact = body.whatsappInboundMessage.interactive;
  message = interact.list_reply?.id || interact.button_reply?.id || interact.list_reply?.title || interact.button_reply?.title;
}

message = message || 'Hola';
let name = body?.whatsappInboundMessage?.customerProfile?.name || 'Cliente';

return {
  sender: String(sender).trim(),
  message: String(message).trim(),
  name: String(name).trim(),
  shop_slug: 'demo'
};

// =====================================================
// HYBRID STATE MACHINE: AI Interpretation + Deterministic Flow
// =====================================================

const msg = $('Extract Message').item.json;
const ctxRaw = $('Get Shop Context').item.json;
const ctx = Array.isArray(ctxRaw) ? ctxRaw[0] : ctxRaw;
const sessRaw = $('Get Session').item.json;
const sess = Array.isArray(sessRaw) ? sessRaw[0] : sessRaw;

const userMessage = msg.message;
const msgLower = userMessage.toLowerCase();
const sender = msg.sender;
const userName = msg.name;
const shopName = ctx?.shop_name || 'Peluquería';
const services = (ctx?.services || '').split(',').map(s => s.trim()).filter(Boolean);
const professionals = (ctx?.professionals || '').split(',').map(s => s.trim()).filter(Boolean);

let currentState = sess?.current_state || 'IDLE';
let intent = sess?.intent || null;
let service = sess?.service || null;
let professional = sess?.professional || null;
let preferredDate = sess?.preferred_date || null;
let preferredTime = sess?.preferred_time || null;

// Get today's date
const today = new Date();
const pad = n => String(n).padStart(2, '0');
const todayStr = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;

// =====================================================
// STEP 1: Detect Intent
// =====================================================
if (!intent || currentState === 'IDLE') {
  if (msgLower.includes('reservar') || msgLower.includes('turno') || msgLower.includes('agendar') || msgLower.includes('cita')) {
    intent = 'BOOK';
    currentState = 'AWAITING_SERVICE';
  } else if (msgLower.includes('cancelar')) {
    intent = 'CANCEL';
  } else if (msgLower.includes('horario') || msgLower.includes('servicio') || msgLower.includes('precio') || msgLower.includes('info')) {
    intent = 'INFO';
  } else if (msgLower.includes('hola') || msgLower.includes('buenas') || msgLower.includes('buen dia') || msgLower.includes('buenos dias')) {
    intent = 'GREET';
  } else if (msgLower.includes('si') || msgLower.includes('dale') || msgLower.includes('ok') || msgLower.includes('sí')) {
    // User confirmed - start booking
    intent = 'BOOK';
    currentState = 'AWAITING_SERVICE';
  } else {
    intent = 'UNKNOWN';
  }
}

// =====================================================
// STEP 2: Extract data from user message
// =====================================================

// Try to extract service
if (currentState === 'AWAITING_SERVICE' && !service) {
  for (const s of services) {
    const sLower = s.toLowerCase().split('(')[0].trim();
    if (userMessage === s || msgLower === s.toLowerCase() || (sLower && msgLower.includes(sLower))) {
      service = s;
      currentState = 'AWAITING_PROFESSIONAL';
      break;
    }
  }
}

// Try to extract professional
if (currentState === 'AWAITING_PROFESSIONAL' && !professional) {
  for (const p of professionals) {
    const pLower = p.toLowerCase();
    const firstName = pLower.split(' ')[0];
    if (userMessage === p || msgLower === pLower || (firstName && msgLower.includes(firstName))) {
      professional = p;
      currentState = 'AWAITING_DATE';
      break;
    }
  }
}

// Try to extract date
if (currentState === 'AWAITING_DATE' && !preferredDate) {
  const iso = d => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;

  if (msgLower.includes('hoy')) {
    preferredDate = todayStr;
    currentState = 'AWAITING_TIME';
  } else if (msgLower.includes('mañana') || msgLower.includes('manana')) {
    const tomorrow = new Date(today);
    tomorrow.setDate(tomorrow.getDate() + 1);
    preferredDate = iso(tomorrow);
    currentState = 'AWAITING_TIME';
  } else {
    const dayMatch = msgLower.match(/(?:el|para|dia)\s*(\d{1,2})/);
    if (dayMatch) {
      const d = new Date();
      d.setDate(Number(dayMatch[1]));
      if (d < today) d.setMonth(d.getMonth() + 1);
      preferredDate = iso(d);
      currentState = 'AWAITING_TIME';
    }
    const fullDateMatch = msgLower.match(/(\d{1,2})[\/-](\d{1,2})/);
    if (!preferredDate && fullDateMatch) {
      const d = new Date();
      d.setDate(Number(fullDateMatch[1]));
      d.setMonth(Number(fullDateMatch[2]) - 1);
      if (d < today) d.setFullYear(d.getFullYear() + 1);
      preferredDate = iso(d);
      currentState = 'AWAITING_TIME';
    }
  }
}

// Try to extract time
if (currentState === 'AWAITING_TIME' && !preferredTime) {
  const timeMatch = userMessage.match(/^(\d{1,2}):(\d{2})/);
  if (timeMatch) {
    preferredTime = `${timeMatch[1].padStart(2, '0')}:${timeMatch[2]}:00`;
    currentState = 'READY_TO_BOOK';
  }
}

// =====================================================
// STEP 3: Determine response based on state
// =====================================================
let action = 'REPLY';
let response = null;
let needsApiCall = null;

if (intent === 'GREET') {
  response = {
    type: 'text',
    text: { body: `¡Hola! 👋 Bienvenido a *${shopName}*. ¿Querés reservar un turno?` }
  };
  currentState = 'IDLE';
  intent = null;

} else if (intent === 'INFO') {
  const serviceList = services.join(', ');
  const profList = professionals.join(', ');
  response = {
    type: 'text',
    text: { body: `ℹ️ *${shopName}*\n\n💇 *Servicios:* ${serviceList}\n💈 *Profesionales:* ${profList}\n\n¿Querés reservar un turno?` }
  };
  currentState = 'IDLE';

} else if (intent === 'BOOK' || (currentState && currentState.startsWith('AWAITING_'))) {
  intent = 'BOOK';

  if (!service) {
    const rows = services.slice(0, 10).map(s => ({ id: s, title: s.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💇 Nuestros Servicios' },
        body: { text: '¡Claro! 😊 ¿Qué servicio te gustaría?' },
        footer: { text: shopName },
        action: { button: 'Ver Servicios', sections: [{ title: 'Servicios', rows: rows }] }
      }
    };
    currentState = 'AWAITING_SERVICE';

  } else if (!professional) {
    const rows = professionals.slice(0, 10).map(p => ({ id: p, title: p.slice(0, 24), description: '' }));
    response = {
      type: 'interactive',
      interactive: {
        type: 'list',
        header: { type: 'text', text: '💈 Nuestros Profesionales' },
        body: { text: `Elegiste: *${service}*\n¿Con quién te gustaría atenderte?` },
        footer: { text: shopName },
        action: { button: 'Ver Profesionales', sections: [{ title: 'Profesionales', rows: rows }] }
      }
    };
    currentState = 'AWAITING_PROFESSIONAL';

  } else if (!preferredDate) {
    response = {
      type: 'text',
      text: { body: `Perfecto! *${service}* con *${professional}*. 📅\n\n¿Para qué fecha querés el turno?\n\nPodés decir: "hoy", "mañana", o una fecha como "el 15" o "10/02"` }
    };
    currentState = 'AWAITING_DATE';

  } else if (!preferredTime) {
    action = 'FETCH_TIMES';
    needsApiCall = 'checkAvailability';
    currentState = 'AWAITING_TIME';

  } else {
    action = 'BOOK_NOW';
    needsApiCall = 'bookAppointment';
  }

} else if (intent === 'CANCEL') {
  action = 'CANCEL_FLOW';
  needsApiCall = 'checkAppointments';

} else {
  response = {
    type: 'text',
    text: { body: `¡Hola! 👋 Puedo ayudarte a:\n\n• *Reservar* un turno\n• *Cancelar* un turno\n• Ver *info* de servicios\n\n¿Qué te gustaría hacer?` }
  };
  currentState = 'IDLE';
}

return {
  action: action,
  response: response,
  needsApiCall: needsApiCall,
  sender: sender,
  updateSession: {
    current_state: currentState,
    intent: intent || '',
    service: service || '',
    professional: professional || '',
    preferred_date: preferredDate || '',
    preferred_time: preferredTime || ''
  },
  context: {
    sender: sender,
    userName: userName,
    shopName: shopName,
    service: service,
    professional: professional,
    preferredDate: preferredDate,
    preferredTime: preferredTime
  }
};

const slots = $json;
const context = $('State Machine').item.json.context;
const updateSession = $('State Machine').item.json.updateSession;
const sender = $('State Machine').item.json.sender;
const shopName = context.shopName;
const preferredDate = context.preferredDate;

if (!slots || slots.length === 0 || slots.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `😕 No hay horarios disponibles para el ${preferredDate} con ${context.professional}.\n\n¿Querés probar otra fecha?` }
    },
    updateSession: updateSession
  };
}

const rows = slots.slice(0, 10).map(slot => {
  const time = slot.start_time ? slot.start_time.substring(11, 16) : String(slot);
  return { id: time, title: time, description: '' };
});

const dateParts = preferredDate.split('-');
const formattedDate = `${dateParts[2]}/${dateParts[1]}`;

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '🕐 Horarios Disponibles' },
      body: { text: `📅 *${formattedDate}* con *${context.professional}*\n\n¿A qué hora te viene bien?` },
      footer: { text: shopName },
      action: { button: 'Ver Horarios', sections: [{ title: 'Horarios', rows: rows }] }
    }
  },
  updateSession: updateSession
};

const result = $json;
const context = $('State Machine').item.json.context;
const sender = $('State Machine').item.json.sender;

if (result.success) {
  const dateParts = context.preferredDate.split('-');
  const formattedDate = `${dateParts[2]}/${dateParts[1]}/${dateParts[0]}`;
  const formattedTime = context.preferredTime.substring(0, 5);

  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `✅ *¡Reserva Confirmada!*\n\n💇 *Servicio:* ${context.service}\n💈 *Profesional:* ${context.professional}\n📅 *Fecha:* ${formattedDate} a las ${formattedTime}\n\n📍 *Lugar:* ${context.shopName}\n\n¡Te esperamos! 🎉` }
    },
    updateSession: { current_state: 'IDLE', intent: '', service: '', professional: '', preferred_date: '', preferred_time: '' }
  };
} else {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `❌ Hubo un problema con la reserva.\n\nError: ${result.error || 'Desconocido'}\n\n¿Querés intentar con otro horario?` }
    },
    updateSession: { current_state: 'AWAITING_TIME', intent: 'BOOK', service: context.service, professional: context.professional, preferred_date: context.preferredDate, preferred_time: '' }
  };
}

const appointments = $json;
const context = $('State Machine').item.json.context;
const sender = $('State Machine').item.json.sender;

if (!appointments || appointments.length === 0 || appointments.error) {
  return {
    sender: sender,
    response: {
      type: 'text',
      text: { body: `No tenés turnos pendientes. 😊\n\n¿Querés reservar uno nuevo?` }
    },
    updateSession: { current_state: 'IDLE', intent: '' }
  };
}

const rows = appointments.slice(0, 10).map(apt => {
  const date = apt.start_time ? apt.start_time.substring(0, 10) : '';
  const time = apt.start_time ? apt.start_time.substring(11, 16) : '';
  const dateParts = date.split('-');
  const shortDate = dateParts.length === 3 ? `${dateParts[2]}/${dateParts[1]}` : date;

  return {
    id: apt.id,
    title: `${shortDate} ${time}`.slice(0, 24),
    description: `${apt.service_name || 'Servicio'}`
  };
});

return {
  sender: sender,
  response: {
    type: 'interactive',
    interactive: {
      type: 'list',
      header: { type: 'text', text: '📋 Tus Turnos' },
      body: { text: 'Seleccioná el turno que querés cancelar:' },
      footer: { text: context.shopName },
      action: { button: 'Ver Turnos', sections: [{ title: 'Turnos Pendientes', rows: rows }] }
    }
  },
  updateSession: { current_state: 'AWAITING_CANCEL_SELECTION', intent: 'CANCEL' }
};
